import{_ as e}from"./chunks/home-assistant-bridge-running-links.utDgUbtF.js";import{_ as s,o as a,c as o,a2 as r}from"./chunks/framework.Desnpdez.js";const n="/mbit-mcpo-proxy-download/guide/images/home-phase-strip-detail.png",i="/mbit-mcpo-proxy-download/guide/images/assistant-bridge-card.png",h="/mbit-mcpo-proxy-download/guide/images/onboarding-before-you-start.png",y=JSON.parse('{"title":"Home","description":"","frontmatter":{},"headers":[],"relativePath":"everyday/home.md","filePath":"everyday/home.md"}'),l={name:"everyday/home.md"};function p(d,t,g,c,u,m){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h1><p><strong>Home</strong> is where you turn the <strong>assistant bridge</strong> on or off and where you copy <strong>links</strong> for other apps.</p><h2 id="what-the-subtitle-means" tabindex="-1">What the subtitle means <a class="header-anchor" href="#what-the-subtitle-means" aria-label="Permalink to &quot;What the subtitle means&quot;">​</a></h2><blockquote><p>Turn on the assistant bridge, then use your connections in ChatGPT, Open WebUI, or other assistants.</p></blockquote><p>The bridge is a small local service. When it runs, your <strong>enabled</strong> connections each get a stable URL on your Mac (by default on port <strong>8000</strong>).</p><h2 id="status-strip-three-steps" tabindex="-1">Status strip (three steps) <a class="header-anchor" href="#status-strip-three-steps" aria-label="Permalink to &quot;Status strip (three steps)&quot;">​</a></h2><p>Read the strip from left to right:</p><table tabindex="0"><thead><tr><th>Step</th><th>Plain meaning</th></tr></thead><tbody><tr><td><strong>Built-in engine</strong></td><td>The packaged runtime is available.</td></tr><tr><td><strong>Bridge</strong></td><td>The assistant bridge is stopped, starting, or running.</td></tr><tr><td><strong>Connections</strong></td><td>How many connections are switched on versus how many you have saved.</td></tr></tbody></table><p><img src="'+n+'" alt="Phase strip on Home"></p><p>The pill in the top-right corner summarises the same story (<strong>Stopped</strong>, <strong>Running</strong>, and so on).</p><h2 id="assistant-bridge-card" tabindex="-1">Assistant bridge card <a class="header-anchor" href="#assistant-bridge-card" aria-label="Permalink to &quot;Assistant bridge card&quot;">​</a></h2><ul><li><strong>Turn on</strong> — starts the bridge.</li><li><strong>Turn off</strong> — stops it.</li><li><strong>Apply changes</strong> — appears after you edited connections; restarts the bridge so new settings apply.</li></ul><p><img src="'+i+'" alt="Assistant bridge area"></p><h2 id="before-you-start-first-time-hints" tabindex="-1">Before you start (first-time hints) <a class="header-anchor" href="#before-you-start-first-time-hints" aria-label="Permalink to &quot;Before you start (first-time hints)&quot;">​</a></h2><p>If the engine is missing or a port is busy, you may see a short <strong>Before you start</strong> card with troubleshooting. Expand <strong>Details for troubleshooting</strong> if the app is still working through a problem.</p><p><img src="'+h+'" alt="Onboarding hints"></p><h2 id="links-for-other-apps" tabindex="-1">Links for other apps <a class="header-anchor" href="#links-for-other-apps" aria-label="Permalink to &quot;Links for other apps&quot;">​</a></h2><p>Once the bridge has run at least once, you get a table of <strong>enabled</strong> connections.</p><ul><li><strong>Copy link</strong> — paste into the assistant.</li><li><strong>Reference</strong> — optional technical page.</li></ul><p><img src="'+e+'" alt="Links table when running"></p><p>If nothing appears here, open <strong>Connections</strong> and make sure at least one connection is <strong>enabled</strong>, then use <strong>Apply changes</strong> on Home.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><strong><a href="./connections.html">Connections</a></strong> — Library and My connections.</li><li><strong><a href="./settings.html">Settings</a></strong> — change the HTTP port or advanced options.</li><li><strong><a href="./open-webui.html">Open WebUI</a></strong> — automatic sync instead of manual links.</li></ul>',23)])])}const _=s(l,[["render",p]]);export{y as __pageData,_ as default};
